     1|/**
     2| * SafeVideo — defensive wrapper around expo-av Video for Android stability.
     3| *
     4| * expo-av on Android is prone to native crashes when:
     5| *   - posterSource/usePoster is enabled with remote URIs
     6| *   - HLS (.m3u8) sources are fed to the legacy player
     7| *   - multiple Video instances mount at once inside a FlatList
     8| *   - shouldPlay flips before the player is ready
     9| *
    10| * This component disables poster on Android, falls back from HLS to MP4, and
    11| * surfaces load errors so the app survives bad videos instead of crashing.
    12| * Poster is rendered as a separate Image layer (not expo-av posterSource).
    13| */
    14|import React, { useEffect, useRef, useState } from 'react';
    15|import { View, Text, Animated, Platform, StyleSheet, TouchableOpacity } from 'react-native';
    16|import { Video, ResizeMode, type VideoReadyForDisplayEvent } from 'expo-av';
    17|import { RefreshCw } from 'lucide-react-native';
    18|import Colors from '@/constants/colors';
    19|
    20|interface SafeVideoProps {
    21|  uri: string | null | undefined;
    22|  posterUri?: string | null | undefined;
    23|  style?: any;
    24|  shouldPlay?: boolean;
    25|  isMuted?: boolean;
    26|  isLooping?: boolean;
    27|  resizeMode?: ResizeMode;
    28|  onProgress?: (progress: number) => void;
    29|  onPlaybackStatusUpdate?: (status: { isPlaying: boolean; durationMillis: number; positionMillis: number }) => void;
    30|  testID?: string;
    31|}
    32|
    33|const GOLD = Colors.primary;
    34|const MAX_RETRIES = 2;
    35|
    36|function pickPlaybackUri(input: string | null | undefined): string | null {
    37|  if (!input) return null;
    38|  // On Android, prefer progressive MP4 over HLS to avoid expo-av native crashes.
    39|  // But if HLS is the ONLY option, still return it rather than null (null causes
    40|  // infinite loading and potential resource leaks from repeated mount cycles).
    41|  if (Platform.OS === 'android' && input.toLowerCase().endsWith('.m3u8')) {
    42|    // Return the HLS URI as a last resort — ExoPlayer can handle basic HLS
    43|    return input;
    44|  }
    45|  return input;
    46|}
    47|
    48|export default function SafeVideo({
    49|  uri,
    50|  posterUri,
    51|  style,
    52|  shouldPlay = false,
    53|  isMuted = true,
    54|  isLooping = true,
    55|  resizeMode = ResizeMode.COVER,
    56|  onProgress,
    57|  onPlaybackStatusUpdate,
    58|  testID}: SafeVideoProps) {
    59|  const videoRef = useRef<Video | null>(null);
    60|  const [error, setError] = useState<string | null>(null);
    61|  const [loading, setLoading] = useState<boolean>(true);
    62|  const [ready, setReady] = useState<boolean>(false);
    63|  const [retryCount, setRetryCount] = useState<number>(0);
    64|  const playbackUri = pickPlaybackUri(uri);
    65|
    66|  // Reset state when the source changes.
    67|  useEffect(() => {
    68|    setError(null);
    69|    setLoading(true);
    70|    setReady(false);
    71|    setRetryCount(0);
    72|  }, [playbackUri]);
    73|
    74|  // CRITICAL: Unload the native ExoPlayer when unmounting.
    75|  // The ref is read in the cleanup closure, but we must use a ref object
    76|  // (not a captured snapshot) so we get the LIVE player instance at
    77|  // cleanup time — not the null value that existed at mount time.
    78|  // Previous bug: `const player = videoRef.current` captured null at
    79|  // mount, so unloadAsync was never called → native players leaked on
    80|  // every reel swipe → memory grew → OOM crash after ~15-25 transitions.
    81|  useEffect(() => {
    82|    return () => {
    83|      try {
    84|        const player = videoRef.current;
    85|        if (player) {
    86|          void player.stopAsync().catch(() => {});
    87|          void player.unloadAsync().catch(() => {});
    88|        }
    89|      } catch {
    90|        // ignore — player may already be gone
    91|      }
    92|    };
    93|  }, []);
    94|
    95|  // Also unload when the URI changes (before the new source loads)
    96|  useEffect(() => {
    97|    return () => {
    98|      try {
    99|        const player = videoRef.current;
   100|        if (player) {
   101|          void player.unloadAsync().catch(() => {});
   102|        }
   103|      } catch {}
   104|    };
   105|  }, [playbackUri]);
   106|
   107|  const handleRetry = () => {
   108|    if (retryCount >= MAX_RETRIES) return;
   109|    setRetryCount((c) => c + 1);
   110|    setError(null);
   111|    setLoading(true);
   112|    setReady(false);
   113|  };
   114|
   115|  if (!playbackUri) {
   116|    // Instagram-style: show dark placeholder with shimmer, not a spinner
   117|    return (
   118|      <View style={[styles.container, style]} testID={testID ? `${testID}-no-source` : undefined}>
   119|        {posterUri ? (
   120|          <View style={[styles.container, style]}>
   121|            <View style={[StyleSheet.absoluteFill, { backgroundColor: '#111' }]} />
   122|          </View>
   123|        ) : (
   124|          <View style={[styles.container, { backgroundColor: '#111' }]} />
   125|        )}
   126|      </View>
   127|    );
   128|  }
   129|
   130|  // Poster on Android is a known crash vector in expo-av; disable it there.
   131|  // The poster is rendered by the parent component (ReelVideoPlayer) as an Image.
   132|  const showPoster = Platform.OS !== 'android' && !!posterUri;
   133|  const posterSource = showPoster ? { uri: posterUri as string } : undefined;
   134|  const usePoster = showPoster;
   135|
   136|  return (
   137|    <View style={[styles.container, style]} testID={testID}>
   138|      <Video
   139|        ref={videoRef}
   140|        source={{ uri: playbackUri }}
   141|        style={StyleSheet.absoluteFill}
   142|        resizeMode={resizeMode}
   143|        shouldPlay={shouldPlay && ready}
   144|        isLooping={isLooping}
   145|        isMuted={isMuted}
   146|        useNativeControls={false}
   147|        usePoster={usePoster}
   148|        posterSource={posterSource}
   149|        onLoadStart={() => setLoading(true)}
   150|        onReadyForDisplay={(e: VideoReadyForDisplayEvent) => {
   151|          setLoading(false);
   152|          setReady(true);
   153|        }}
   154|        onLoad={(status) => {
   155|          setLoading(false);
   156|          if (status.isLoaded) {
   157|            setReady(true);
   158|          }
   159|        }}
   160|        onError={(err) => {
   161|          setLoading(false);
   162|          setReady(false);
   163|          setError(typeof err === 'string' ? err : 'Video failed to load');
   164|          if (__DEV__) {
   165|            console.warn('[SafeVideo] load error:', err);
   166|          }
   167|        }}
   168|        onPlaybackStatusUpdate={(status) => {
   169|          if (status.isLoaded && status.durationMillis && status.durationMillis > 0) {
   170|            onProgress?.(status.positionMillis / status.durationMillis);
   171|            onPlaybackStatusUpdate?.({
   172|              isPlaying: status.isPlaying ?? false,
   173|              durationMillis: status.durationMillis,
   174|              positionMillis: status.positionMillis ?? 0});
   175|          }
   176|        }}
   177|      />
   178|      {loading && !error && (
   179|        <View style={styles.overlay} pointerEvents="none">
   180|          {/* Instagram-style: subtle dark overlay while video buffers — no spinner */}
   181|          <View style={[StyleSheet.absoluteFill, { backgroundColor: 'rgba(0,0,0,0.15)' }]} />
   182|        </View>
   183|      )}
   184|      {error && (
   185|        <View style={styles.overlay} pointerEvents="auto">
   186|          {retryCount < MAX_RETRIES ? (
   187|            <TouchableOpacity style={styles.retryBtn} onPress={handleRetry} activeOpacity={0.8}>
   188|              <RefreshCw size={16} color="#000" />
   189|              <Text style={styles.retryText}>Retry</Text>
   190|            </TouchableOpacity>
   191|          ) : (
   192|            <Text style={{ color: 'rgba(255,255,255,0.6)', fontSize: 12 }}>Video unavailable</Text>
   193|          )}
   194|        </View>
   195|      )}
   196|    </View>
   197|  );
   198|}
