#!/usr/bin/env node
/**
 * Git Data API push for IVX media lifecycle changes.
 *
 * Creates a new commit on top of GitHub main with the modified/new files,
 * then updates the main ref. Used because direct git push is blocked by a
 * missing LFS object in this sandbox.
 */
import fs from 'node:fs';
import path from 'node:path';

const OWNER = 'ibb142';
const REPO = 'ivx-holdings-platform';
const TOKEN = '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';
const BASE_COMMIT = '9d5c0d2daedbbcb9cbf37ced9d98cc86f4ee56bf';
const PROJECT_ROOT = '/home/user/rork-app';

const FILES = [
  '.rork/plans/ivx-ia-final-certification-terminal-stat_1784657316341.plan.md',
  'expo/app/ivx/chat.tsx',
  'expo/app/videos.tsx',
  'expo/src/modules/chat/components/MessageBubble.tsx',
  'expo/src/modules/media-lifecycle/__tests__/mediaLifecycle.test.ts',
  'expo/src/modules/media-lifecycle/components/ControlledImage.tsx',
  'expo/src/modules/media-lifecycle/components/ControlledVideo.tsx',
  'expo/src/modules/media-lifecycle/components/ViewportTracker.tsx',
  'expo/src/modules/media-lifecycle/controller.ts',
  'expo/src/modules/media-lifecycle/hooks.ts',
  'expo/src/modules/media-lifecycle/store.ts',
  'expo/src/modules/media-lifecycle/types.ts',
  'expo/src/modules/media-lifecycle/utils/diagnostics.ts',
];

const COMMIT_MESSAGE = `feat(media-lifecycle): centralized IVX media lifecycle controller + IVX IA Chat integration

- Add MediaLifecycleController with idle/prefetch/ready/visible/active/paused/error/released states
- Enforce global budgets: 1 active video, 2 prepared videos, visible image window +/- 2, fast-scroll protection
- Add ControlledImage and ControlledVideo wrappers for progressive media loading
- Add ViewportTracker and useMediaLifecycleList for FlatList integration
- Integrate media lifecycle into IVX IA Chat (message images/videos + viewport + scroll tracking)
- Integrate media lifecycle into Reels (registration + viewport/scroll tracking)
- Add dev-only diagnostics and 12/12 unit tests for controller logic`;

async function githubApi(path, body, method = 'POST') {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}${path}`;
  const res = await fetch(url, {
    method,
    headers: {
      Authorization: `token ${TOKEN}`,
      Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'X-GitHub-Api-Version': '2022-11-28',
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  if (!res.ok) {
    throw new Error(`GitHub API ${method} ${path} failed: ${res.status} ${text}`);
  }
  return JSON.parse(text);
}

function buildTreeEntries() {
  return FILES.map((file) => {
    const content = fs.readFileSync(path.join(PROJECT_ROOT, file), 'utf-8');
    return {
      path: file,
      mode: '100644',
      type: 'blob',
      content,
    };
  });
}

async function main() {
  // 1. Get base commit to retrieve its tree SHA
  const baseCommit = await githubApi(`/git/commits/${BASE_COMMIT}`, null, 'GET');
  const baseTreeSha = baseCommit.tree.sha;
  console.log('baseTreeSha', baseTreeSha);

  // 2. Create new tree with changed files on top of base tree
  const treeEntries = buildTreeEntries();
  const newTree = await githubApi('/git/trees', {
    base_tree: baseTreeSha,
    tree: treeEntries,
  });
  console.log('newTreeSha', newTree.sha);

  // 3. Create commit
  const newCommit = await githubApi('/git/commits', {
    message: COMMIT_MESSAGE,
    parents: [BASE_COMMIT],
    tree: newTree.sha,
  });
  console.log('newCommitSha', newCommit.sha);

  // 4. Update main ref
  await githubApi('/git/refs/heads/main', { sha: newCommit.sha }, 'PATCH');
  console.log('updated main to', newCommit.sha);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

